package com.studenthub.util;
import com.studenthub.model.Attachment;import jakarta.servlet.http.*;import java.io.*;import java.nio.file.*;
public final class MediaResponse{private MediaResponse(){}public static void serve(HttpServletRequest q,HttpServletResponse r,Attachment a,Path file)throws IOException{long size=Files.size(file),start=0,end=size-1;String range=q.getHeader("Range");if(range!=null&&range.matches("bytes=\\d*-\\d*")){String[] values=range.substring(6).split("-",-1);if(!values[0].isBlank())start=Long.parseLong(values[0]);if(!values[1].isBlank())end=Math.min(end,Long.parseLong(values[1]));if(start<0||start>end||start>=size){r.setHeader("Content-Range","bytes */"+size);r.sendError(416);return;}r.setStatus(206);r.setHeader("Content-Range","bytes "+start+"-"+end+"/"+size);}r.setContentType(a.mimeType());r.setHeader("Accept-Ranges","bytes");r.setHeader("X-Content-Type-Options","nosniff");r.setHeader("Cache-Control","private, max-age=3600");boolean inline=!"1".equals(q.getParameter("download"))&&(a.isImage()||a.isVideo()||a.isAudio());r.setHeader("Content-Disposition",(inline?"inline":"attachment")+"; filename*=UTF-8''"+java.net.URLEncoder.encode(a.originalFilename(),java.nio.charset.StandardCharsets.UTF_8).replace("+","%20"));long length=end-start+1;r.setContentLengthLong(length);try(InputStream input=Files.newInputStream(file);OutputStream output=r.getOutputStream()){input.skipNBytes(start);byte[] buffer=new byte[64*1024];long remaining=length;while(remaining>0){int count=input.read(buffer,0,(int)Math.min(buffer.length,remaining));if(count<0)break;output.write(buffer,0,count);remaining-=count;}}}}
